import React, { useState } from 'react';
import { Bike, DollarSign, CheckCircle2, AlertTriangle, Plus } from 'lucide-react';

export default function Riders() {
  const [riders, setRiders] = useState([
    {
      id: 1,
      name: 'Rakib Hasan',
      phone: '01811223344',
      cashInHand: 2450,
      onlineTotal: 5800,
      limit: 2000,
      status: 'locked', // ক্যাশ লিমিট পার হওয়ায় লক
    },
    {
      id: 2,
      name: 'Sumon Ahmed',
      phone: '01822334455',
      cashInHand: 620,
      onlineTotal: 3400,
      limit: 2000,
      status: 'active',
    }
  ]);

  const clearCash = (id) => {
    setRiders(riders.map(r => r.id === id ? { ...r, cashInHand: 0, status: 'active' } : r));
    alert('রাইডারের ক্যাশ সফলভাবে ক্লিয়ার হয়েছে এবং আইডি আনলক করা হয়েছে!');
  };

  return (
    <div className="p-8 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-black text-gray-900">Riders & Cash Handover</h1>
          <p className="text-sm text-gray-500">হাতে নগদ টাকা (COD), অনলাইন কালেকশন এবং সেটেলমেন্ট</p>
        </div>
        <button className="flex items-center gap-2 px-4 py-2.5 bg-emerald-600 text-white rounded-xl font-bold hover:bg-emerald-700 shadow-md shadow-emerald-600/20">
          <Plus className="w-4 h-4" /> Add Rider
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
        {riders.map((rider) => (
          <div key={rider.id} className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm space-y-4">
            <div className="flex justify-between items-start">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-emerald-50 text-emerald-700 flex items-center justify-center font-bold">
                  <Bike className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="font-bold text-gray-900">{rider.name}</h3>
                  <p className="text-xs text-gray-500">{rider.phone}</p>
                </div>
              </div>
              <span className={`px-2.5 py-1 rounded-md text-xs font-bold uppercase ${
                rider.status === 'locked' ? 'bg-red-100 text-red-700' : 'bg-emerald-100 text-emerald-800'
              }`}>
                {rider.status}
              </span>
            </div>

            <div className="grid grid-cols-2 gap-3 bg-gray-50 p-3.5 rounded-xl border border-gray-100">
              <div>
                <span className="text-xs text-gray-500 block">Cash in Hand (COD)</span>
                <span className={`text-base font-black ${rider.cashInHand > rider.limit ? 'text-red-600' : 'text-gray-800'}`}>
                  ৳ {rider.cashInHand}
                </span>
                <span className="text-[10px] text-gray-400 block">Limit: ৳{rider.limit}</span>
              </div>
              <div>
                <span className="text-xs text-gray-500 block">Online Paid Delivery</span>
                <span className="text-base font-black text-emerald-600">৳ {rider.onlineTotal}</span>
              </div>
            </div>

            <div className="flex items-center justify-between pt-1">
              {rider.cashInHand > rider.limit && (
                <span className="text-xs text-red-600 font-bold flex items-center gap-1">
                  <AlertTriangle className="w-3.5 h-3.5" /> Limit Exceeded
                </span>
              )}
              <button
                onClick={() => clearCash(rider.id)}
                className="ml-auto flex items-center gap-1.5 px-4 py-2 bg-emerald-600 text-white rounded-xl text-xs font-bold hover:bg-emerald-700"
              >
                <CheckCircle2 className="w-4 h-4" /> Clear / Settle Cash
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
